// --- apm.FDelta..Init
// Set all fields to initial values.
inline void apm::FDelta_Init(apm::FDelta& parent) {
    parent.nadd = i32(0);
    parent.nmod = i32(0);
    parent.ndel = i32(0);
    parent.ind_delta_next = (apm::FDelta*)-1; // (apm.FDb.ind_delta) not-in-hash
    parent.ind_delta_hashval = 0; // stored hash value
}

// --- apm.FDelta..Ctor
inline  apm::FDelta::FDelta() {
    apm::FDelta_Init(*this);
}

// --- apm.FDelta..Dtor
inline  apm::FDelta::~FDelta() {
    apm::FDelta_Uninit(*this);
}

// --- apm.FField.c_substr.InsertMaybe
// Insert row into pointer index. Return final membership status.
inline bool apm::c_substr_InsertMaybe(apm::FField& parent, apm::FSubstr& row) {
    apm::FSubstr* ptr = parent.c_substr;
    bool retval = (ptr == NULL) | (ptr == &row);
    if (retval) {
        parent.c_substr = &row;
    }
    return retval;
}

// --- apm.FField.c_substr.Remove
// Remove element from index. If element is not in index, do nothing.
inline void apm::c_substr_Remove(apm::FField& parent, apm::FSubstr& row) {
    apm::FSubstr *ptr = parent.c_substr;
    if (LIKELY(ptr == &row)) {
        parent.c_substr = NULL;
    }
}

